using AcxiomCRM.Data; using AcxiomCRM.Models; using AcxiomCRM.Services; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore; using System.Security.Claims;
namespace AcxiomCRM.Controllers;
[Authorize] public class ActivitiesController:Controller { private readonly ApplicationDbContext _db; private readonly IAuditService _audit; public ActivitiesController(ApplicationDbContext db,IAuditService audit){_db=db;_audit=audit;}
 public async Task<IActionResult> Index(string? q,string? status,int page=1){var query=_db.Activities.AsQueryable(); if(!User.IsInRole("Admin")&&!User.IsInRole("Manager")){var uid=User.FindFirstValue(ClaimTypes.NameIdentifier); query=query.Where(x=>x.AssignedTo==uid);} if(!string.IsNullOrWhiteSpace(q)){var s=q.Trim(); query=query.Where(x=>x.Subject.Contains(s)||(x.Description!=null&&x.Description.Contains(s)));} if(!string.IsNullOrWhiteSpace(status)) query=query.Where(x=>x.Status==status); ViewBag.Query=q;ViewBag.Status=status;ViewBag.Page=page;ViewBag.Pages=(int)Math.Ceiling(await query.CountAsync()/10.0);return View(await query.OrderByDescending(x=>x.Id).Skip((Math.Max(1,page)-1)*10).Take(10).ToListAsync());}
 public async Task<IActionResult> Details(int id){var item=await _db.Activities.FindAsync(id);if(item==null)return NotFound();return View(item);}
 
 [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> Create(Activity item){if(item.CustomerId==null&&item.LeadId==null)ModelState.AddModelError("","Select a related customer or lead.");if(!ModelState.IsValid)return View(item);item.CreatedBy=User.FindFirstValue(ClaimTypes.NameIdentifier);if(item is Activity assigned && string.IsNullOrEmpty(assigned.AssignedTo)){assigned.AssignedTo=item.CreatedBy;}_db.Activities.Add(item);try{await _db.SaveChangesAsync();await _audit.WriteAsync("Create","Activity",item.Id.ToString(),newValue:System.Text.Json.JsonSerializer.Serialize(item));TempData["Success"]="Activity created successfully.";return RedirectToAction(nameof(Index));}catch(DbUpdateException){ModelState.AddModelError("","Could not save this record. Check for duplicate values and related records.");return View(item);}}
 public async Task<IActionResult> Edit(int id){var item=await _db.Activities.FindAsync(id);return item==null?NotFound():View(item);}
 [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> Edit(int id,Activity item){if(id!=item.Id)return BadRequest();if(item.CustomerId==null&&item.LeadId==null)ModelState.AddModelError("","Select a related customer or lead.");if(!ModelState.IsValid)return View(item);var old=await _db.Activities.AsNoTracking().FirstOrDefaultAsync(x=>x.Id==id);if(old==null)return NotFound();_db.Entry(item).State=EntityState.Modified;_db.Entry(item).Property(x=>x.CreatedDate).IsModified=false;_db.Entry(item).Property(x=>x.CreatedBy).IsModified=false;try{await _db.SaveChangesAsync();await _audit.WriteAsync("Update","Activity",id.ToString(),System.Text.Json.JsonSerializer.Serialize(old),System.Text.Json.JsonSerializer.Serialize(item));TempData["Success"]="Activity updated successfully.";return RedirectToAction(nameof(Index));}catch(DbUpdateException){ModelState.AddModelError("","Could not update this record. Check duplicate values and relationships.");return View(item);}}
 [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> Delete(int id){var item=await _db.Activities.FindAsync(id);if(item==null)return NotFound();var old=System.Text.Json.JsonSerializer.Serialize(item);_db.Activities.Remove(item);try{await _db.SaveChangesAsync();await _audit.WriteAsync("Delete/Deactivate","Activity",id.ToString(),old);TempData["Success"]="Delete activity completed.";}catch(DbUpdateException){TempData["Error"]="This record is referenced by other records and cannot be deleted. Deactivate it instead.";}return RedirectToAction(nameof(Index));}

}
